select is((select count(*)from permissions),47::bigint,'permission registry 47');
select is((select count(*)from permissions where critical),6::bigint,'critical registry remains six');
select set_eq($$select code from permissions where code like 'purchases.%'$$,$$select * from (values('purchases.view'),('purchases.post'),('purchases.reverse'),('purchases.draft.manage'),('purchases.cost.view'),('purchases.post_daily'))x(code)$$,'purchase permission set exact');
