select is((select count(*)from permission_profile_permissions ppp join permissions p on p.id=ppp.permission_id where ppp.permission_profile_id='00000000-0000-0000-0000-000000000102'),16::bigint,'seller remains 16');
select is((select count(*)from permission_profile_permissions ppp join permissions p on p.id=ppp.permission_id where ppp.permission_profile_id='00000000-0000-0000-0000-000000000102' and p.code like 'purchases.%'),0::bigint,'seller no purchase permissions');
select ok((select tgenabled='O'from pg_trigger where tgrelid='permissions'::regclass and tgname='v2_permissions_prevent_insert'),'permission insert guard restored');
select throws_ok($$insert into permissions(code,module,description,critical)values('bad.13','bad','bad',false)$$,'P0001','V2_PERMISSION_REGISTRY_MUTATION_FORBIDDEN','runtime permission insert denied');

