select ok(not exists(select 1 from pg_constraint c where c.contype='f'and c.conrelid in(select format('public.%I',t)::regclass from(values ('purchase_documents'),('purchase_lines'),('purchase_additional_costs'),('purchase_cost_allocations'),('product_batches_v2'),('daily_delivery_templates'),('daily_delivery_documents'),('inventory_documents'),('inventory_document_lines'),('warehouse_transfers'),('warehouse_transfer_lines'),('inventory_movements'),('inventory_balances'))x(t))and c.confrelid in('suppliers'::regclass,'customers'::regclass,'products'::regclass,'units'::regclass,'devices'::regclass,'product_batches'::regclass,'stock_movements'::regclass)),'new graph has no forbidden legacy FK');
